CREATE TABLE IF NOT EXISTS SemanticRecords(AssetId VARCHAR(100) NOT NULL, SourceElementId VARCHAR(255) NOT NULL, Name VARCHAR(255) NOT NULL, ClassId VARCHAR(100) NOT NULL, SearchText TEXT NOT NULL, RecordJson LONGTEXT NOT NULL, PRIMARY KEY(AssetId,SourceElementId), INDEX(AssetId,ClassId), FULLTEXT INDEX(SearchText));
CREATE TABLE IF NOT EXISTS SemanticDatasets(AssetId VARCHAR(100) PRIMARY KEY, RecordCount BIGINT NOT NULL, CreatedAt VARCHAR(40) NOT NULL);
